export enum Position {
  QB = 'QB',
  RB = 'RB',
  WR = 'WR',
  OL = 'OL',
  DL = 'DL',
  LB = 'LB',
  DB = 'DB',
  K = 'K'
}

export enum PlayerYear {
  FR = 'FR',
  SO = 'SO',
  JR = 'JR',
  SR = 'SR',
  RS_FR = 'RS-FR',
  RS_SO = 'RS-SO',
  RS_JR = 'RS-JR',
  RS_SR = 'RS-SR'
}

export type Conference = 
  | 'SEC' | 'Big Ten' | 'ACC' | 'Big 12' | 'Pac-12'
  | 'AAC' | 'Mountain West' | 'Sun Belt' | 'MAC' | 'CUSA' 
  | 'Independent';

export enum SeasonStage {
  PRE_SEASON = 'PRE_SEASON',
  REGULAR_SEASON = 'REGULAR_SEASON',
  CONFERENCE_CHAMPIONSHIP = 'CONFERENCE_CHAMPIONSHIP',
  POST_SEASON = 'POST_SEASON',
  COACHING_CAROUSEL = 'COACHING_CAROUSEL',
  RETENTION = 'RETENTION',
  TRANSFER_PORTAL = 'TRANSFER_PORTAL',
  OFF_SEASON = 'OFF_SEASON'
}

export type AIProvider = 'gemini' | 'ollama';

export interface AISettings {
  provider: AIProvider;
  ollamaUrl: string;
  ollamaModel: string;
}

export interface Coach {
  name: string;
  almaMater: string;
  level: number;
  prestige: number;
  offense: string;
  defense: string;
  history: string[];
  stats: {
    wins: number;
    losses: number;
    confChamps: number;
    natChamps: number;
  };
}

export interface Player {
  id: string;
  name: string;
  position: Position;
  year: PlayerYear;
  rating: number;
  hometown: string;
  stats: {
    games: number;
    yards: number;
    touchdowns: number;
    interceptions?: number;
    tackles?: number;
  };
  potential: number;
  leavingStatus?: 'GRADUATING' | 'NFL' | 'TRANSFER' | null;
  isRedshirting?: boolean;
}

export type RecruitPriority = 'Pro Potential' | 'Playing Time' | 'Academics' | 'Distance' | 'Prestige' | 'Coaching';

export interface Recruit extends Player {
  interest: number;
  offers: string[];
  committedTo: string | null;
  stars: number;
  scoutingReport?: string;
  isScouted: boolean;
  isOffered: boolean;
  isTargeted: boolean;
  recruitType: 'HS' | 'TRANSFER';
  priority: RecruitPriority;
}

export interface Team {
  id: string;
  name: string;
  nickname: string;
  abbreviation: string;
  color: string;
  secondaryColor?: string;
  prestige: number;
  stars: number;
  conference: Conference;
  stats: {
    wins: number;
    losses: number;
    confWins: number;
    confLosses: number;
    pointsFor: number;
    pointsAgainst: number;
    rank: number;
    streak: number;
  };
  roster: Player[];
  strategy: {
    offense: 'Balanced' | 'Spread' | 'Pro-Style' | 'Option' | 'Air Raid' | 'Run Heavy';
    defense: 'Balanced' | '4-3' | '3-4' | 'Blitz Heavy' | '4-2-5' | '3-3-5';
    aggression: number;
    clockManagement: 'Aggressive' | 'Balanced' | 'Conservative';
    fourthDownTendency: 'Aggressive' | 'Balanced' | 'Conservative';
  };
}

export interface GameStats {
  homeScore: number;
  awayScore: number;
  quarters: number[];
  passingYards: number;
  rushingYards: number;
  turnovers: number;
  possessionTime: string;
}

export interface GameResult {
  week: number;
  opponentId: string;
  isHome: boolean;
  result: 'W' | 'L' | null;
  stats: GameStats | null;
  summary: string;
  playByPlayHighlights: string[];
}

export interface Matchup {
  id: string;
  week: number;
  homeTeamId: string;
  awayTeamId: string;
  played: boolean;
  winnerId?: string;
  homeScore?: number;
  awayScore?: number;
  isUserGame: boolean;
  isConferenceGame: boolean;
  isPlayoff?: boolean;
  label?: string;
}

export interface Storyline {
  id: string;
  title: string;
  content: string;
  importance: 'LOW' | 'MED' | 'HIGH';
  tags: string[];
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { Team, GameResult, AISettings, Storyline } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const gameSimulationSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    homeScore: { type: Type.INTEGER },
    awayScore: { type: Type.INTEGER },
    quarters: { 
      type: Type.ARRAY, 
      items: { type: Type.INTEGER },
      description: "Scores for Home team by quarter" 
    },
    summary: { type: Type.STRING, description: "A detailed 4-sentence summary of the game narrative." },
    playByPlayHighlights: { 
      type: Type.ARRAY, 
      items: { type: Type.STRING },
      description: "5 key moments from the game with timestamps"
    },
    stats: {
      type: Type.OBJECT,
      properties: {
        passingYards: { type: Type.INTEGER },
        rushingYards: { type: Type.INTEGER },
        turnovers: { type: Type.INTEGER },
        possessionTime: { type: Type.STRING }
      }
    }
  },
  required: ["homeScore", "awayScore", "summary", "playByPlayHighlights", "stats"]
};

const storylineSchema: Schema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.STRING },
      title: { type: Type.STRING },
      content: { type: Type.STRING },
      importance: { type: Type.STRING, enum: ["LOW", "MED", "HIGH"] },
      tags: { type: Type.ARRAY, items: { type: Type.STRING } }
    },
    required: ["id", "title", "content", "importance", "tags"]
  }
};

export const simulateGameWithAI = async (
  homeTeam: Team, 
  awayTeam: Team,
  settings: AISettings
): Promise<GameResult | null> => {
  try {
    const prompt = `
      Simulate a college football game between:
      HOME: ${homeTeam.name} (Rank: #${homeTeam.stats.rank || 'NR'}, OVR: ${homeTeam.prestige})
      AWAY: ${awayTeam.name} (Rank: #${awayTeam.stats.rank || 'NR'}, OVR: ${awayTeam.prestige})

      Home Strategy: ${homeTeam.strategy.offense} / ${homeTeam.strategy.defense} (Aggression: ${homeTeam.strategy.aggression})
      Away Strategy: ${awayTeam.strategy.offense} / ${awayTeam.strategy.defense}

      Create a realistic score based on team prestige. High prestige teams should usually beat low prestige ones unless it's a major upset.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: gameSimulationSchema,
        temperature: 0.8
      }
    });

    const data = JSON.parse(response.text || '{}');
    const quarters = data.quarters && data.quarters.length === 4 ? data.quarters : [0,0,0,0];

    return {
      week: 0,
      opponentId: awayTeam.id,
      isHome: true,
      result: data.homeScore > data.awayScore ? 'W' : 'L',
      stats: {
        homeScore: data.homeScore,
        awayScore: data.awayScore,
        quarters: quarters,
        passingYards: data.stats?.passingYards || 0,
        rushingYards: data.stats?.rushingYards || 0,
        turnovers: data.stats?.turnovers || 0,
        possessionTime: data.stats?.possessionTime || "30:00"
      },
      summary: data.summary || "The game concludes with standard results.",
      playByPlayHighlights: data.playByPlayHighlights || []
    };
  } catch (error) {
    console.error("AI Simulation failed:", error);
    return null;
  }
};

export const generateWeeklyStorylines = async (
  week: number, 
  topPerformers: string[], 
  settings: AISettings
): Promise<Storyline[]> => {
  try {
    const prompt = `
      Generate 3 compelling college football news storylines for Week ${week}.
      Context: Top teams: ${topPerformers.join(', ')}.
      Include topics like:
      - A major upset rumor.
      - A player entering the Heisman conversation.
      - A coaching rumor or "hot seat" news.
      Output as a JSON array of Storyline objects.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: storylineSchema
      }
    });

    return JSON.parse(response.text || '[]');
  } catch (e) {
    return [
      { id: '1', title: 'Season Heating Up', content: 'As the schedule reaches its midpoint, every game has playoff implications.', importance: 'MED', tags: ['Season'] }
    ];
  }
};

import React, { useState, useEffect } from 'react';
import { ICONS, INITIAL_LEAGUE, generateBalancedRoster, calculateStars, generateRandomPlayer } from './constants';
import { Team, GameResult, Recruit, Position, Matchup, SeasonStage, Coach, PlayerYear, Player, AISettings, Storyline, RecruitPriority } from './types';
import { PlayerCard } from './components/PlayerCard';
import { StrategyPanel } from './components/StrategyPanel';
import { simulateGameWithAI, generateWeeklyStorylines } from './services/geminiService';
import { generateSeasonSchedule, simulateMatch, getStandings, generatePlayoffs, getAPTop25, getCFPTop25, generateConferenceChampionships } from './utils/seasonUtils';

const TABS = {
  DASHBOARD: 'Home',
  RESULTS: 'Scores',
  RANKINGS: 'Polls',
  ROSTER: 'Roster',
  RECRUITING: 'Recruiting',
  STRATEGY: 'Strategy',
  STANDINGS: 'Conferences',
  PROFILE: 'Coach',
  SETTINGS: 'Settings'
};

const PRIORITIES: RecruitPriority[] = ['Pro Potential', 'Playing Time', 'Academics', 'Distance', 'Prestige', 'Coaching'];

const App = () => {
  const [viewState, setViewState] = useState<'CREATE_COACH' | 'JOB_OFFERS' | 'DYNASTY_HUB'>('CREATE_COACH');
  const [seasonStage, setSeasonStage] = useState<SeasonStage>(SeasonStage.PRE_SEASON);
  const [coach, setCoach] = useState<Coach>({
    name: '', almaMater: '', level: 1, prestige: 10, offense: 'Balanced', defense: '4-3', history: [], stats: { wins: 0, losses: 0, confChamps: 0, natChamps: 0 }
  });

  const [league, setLeague] = useState<Team[]>(INITIAL_LEAGUE);
  const [userTeamId, setUserTeamId] = useState<string>('');
  const [jobOffers, setJobOffers] = useState<Team[]>([]);
  const [schedule, setSchedule] = useState<Matchup[]>([]);
  const [storylines, setStorylines] = useState<Storyline[]>([]);
  const [activeTab, setActiveTab] = useState(TABS.DASHBOARD);
  const [week, setWeek] = useState(0);
  const [simResult, setSimResult] = useState<GameResult | null>(null);
  const [loading, setLoading] = useState(false);
  const [recruitingPoints, setRecruitingPoints] = useState(100);
  const [recruits, setRecruits] = useState<Recruit[]>([]);
  const [scholarshipsAvailable, setScholarshipsAvailable] = useState(25);
  const [aiSettings, setAiSettings] = useState<AISettings>({ provider: 'gemini', ollamaUrl: '', ollamaModel: '' });

  const userTeam = league.find(t => t.id === userTeamId);
  const weeklySchedule = schedule.filter(m => m.week === week);
  const userMatchup = weeklySchedule.find(m => m.homeTeamId === userTeamId || m.awayTeamId === userTeamId);
  const currentOpponent = userMatchup 
    ? league.find(t => t.id === (userMatchup.homeTeamId === userTeamId ? userMatchup.awayTeamId : userMatchup.homeTeamId))
    : null;

  const initRecruitingPool = (teamPrestige: number) => {
    const newRecruits: Recruit[] = [];
    for (let i = 0; i < 80; i++) {
      const p = generateRandomPlayer(`rec-${i}`, undefined, 60, 85);
      newRecruits.push({
        ...p,
        interest: Math.floor(Math.random() * 20) + (teamPrestige / 2),
        offers: [],
        committedTo: null,
        stars: p.rating >= 80 ? 5 : p.rating >= 75 ? 4 : 3,
        isScouted: false,
        isOffered: false,
        isTargeted: false,
        recruitType: 'HS',
        priority: PRIORITIES[Math.floor(Math.random() * PRIORITIES.length)]
      });
    }
    setRecruits(newRecruits);
  };

  const handleCreateCoach = () => {
    if (!coach.name) return;
    const potentialTeams = league.filter(t => t.prestige < 65);
    setJobOffers(potentialTeams.sort(() => Math.random() - 0.5).slice(0, 5));
    setViewState('JOB_OFFERS');
  };

  const handleSelectJob = (teamId: string) => {
    const team = league.find(t => t.id === teamId)!;
    setLeague(prev => prev.map(t => t.id === teamId ? { ...t, roster: generateBalancedRoster(teamId, t.prestige) } : t));
    setUserTeamId(teamId);
    setSchedule(generateSeasonSchedule(league));
    initRecruitingPool(team.prestige);
    setViewState('DYNASTY_HUB');
    setSeasonStage(SeasonStage.PRE_SEASON);
  };

  const advanceWeek = async () => {
    setLoading(true);
    const updatedSchedule = schedule.map(match => {
      if (match.week !== week || match.played) return match;
      if (match.id === userMatchup?.id && simResult) {
         return { ...match, played: true, homeScore: simResult.stats?.homeScore, awayScore: simResult.stats?.awayScore, winnerId: simResult.result === 'W' ? userTeamId : currentOpponent?.id };
      }
      const home = league.find(t => t.id === match.homeTeamId)!;
      const away = league.find(t => t.id === match.awayTeamId)!;
      const res = simulateMatch(home, away);
      return { ...match, played: true, homeScore: res.homeScore, awayScore: res.awayScore, winnerId: res.homeScore > res.awayScore ? home.id : away.id };
    });

    const newWeek = week + 1;
    const topTeams = getAPTop25(league).slice(0, 5).map(t => t.name);
    const newStorylines = await generateWeeklyStorylines(newWeek, topTeams, aiSettings);

    setSchedule(updatedSchedule);
    setWeek(newWeek);
    setStorylines(newStorylines);
    setSimResult(null);
    setRecruitingPoints(100 + (userTeam?.prestige || 0));
    setLoading(false);
  };

  const handleSimulateUserGame = async () => {
    if (!userTeam || !currentOpponent) return;
    setLoading(true);
    const result = await simulateGameWithAI(userTeam, currentOpponent, aiSettings);
    if (result) setSimResult(result);
    setLoading(false);
  };

  const renderDashboard = () => (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-fade-in">
      <div className="lg:col-span-2 space-y-8">
        {/* Next Game Card */}
        <section className="bg-slate-800 rounded-3xl border border-slate-700 overflow-hidden shadow-2xl">
          <div className="bg-gradient-to-r from-slate-700 to-slate-800 px-8 py-4 flex justify-between items-center">
            <h2 className="text-sm font-black text-slate-400 uppercase tracking-widest">Next Matchup • Week {week}</h2>
            <span className="text-xs bg-emerald-500/20 text-emerald-400 px-3 py-1 rounded-full font-bold">LIVE BROADCAST</span>
          </div>
          <div className="p-10 text-center">
            {!currentOpponent ? (
              <div className="py-12">
                <ICONS.Calendar className="w-16 h-16 text-slate-600 mx-auto mb-4" />
                <h3 className="text-2xl font-bold text-white">Bye Week</h3>
                <p className="text-slate-400">Rest up and focus on recruiting.</p>
                <button onClick={advanceWeek} className="mt-8 px-10 py-4 bg-slate-700 hover:bg-slate-600 text-white font-bold rounded-2xl transition-all">Advance Week</button>
              </div>
            ) : simResult ? (
              <div className="animate-in zoom-in-95 duration-500">
                <div className="flex justify-around items-center mb-10">
                  <div className="text-center">
                    <div className="text-6xl font-black text-white mb-2">{simResult.stats?.homeScore}</div>
                    <div className="text-emerald-400 font-black tracking-tighter">{userTeam?.abbreviation}</div>
                  </div>
                  <div className="text-slate-500 font-bold uppercase text-xs">Final</div>
                  <div className="text-center">
                    <div className="text-6xl font-black text-white mb-2">{simResult.stats?.awayScore}</div>
                    <div className="text-slate-400 font-black tracking-tighter">{currentOpponent.abbreviation}</div>
                  </div>
                </div>
                <p className="text-slate-300 italic mb-8 max-w-lg mx-auto leading-relaxed">"{simResult.summary}"</p>
                <div className="flex gap-4">
                  <button onClick={advanceWeek} className="flex-1 py-4 bg-emerald-600 hover:bg-emerald-500 text-white font-black rounded-2xl shadow-xl shadow-emerald-900/40">Finish Week</button>
                </div>
              </div>
            ) : (
              <div>
                <div className="flex justify-center items-center gap-12 mb-10">
                  <div className="text-center group">
                    <div className={`w-24 h-24 ${userTeam?.color} rounded-3xl flex items-center justify-center text-3xl font-black text-white shadow-2xl mb-4 group-hover:scale-105 transition-transform`}>{userTeam?.abbreviation}</div>
                    <div className="font-black text-white text-xl">{userTeam?.nickname}</div>
                    <div className="text-xs text-slate-500">{userTeam?.stats.wins}-{userTeam?.stats.losses}</div>
                  </div>
                  <div className="text-4xl font-black text-slate-700 italic">VS</div>
                  <div className="text-center group">
                    <div className={`w-24 h-24 ${currentOpponent.color} rounded-3xl flex items-center justify-center text-3xl font-black text-white shadow-2xl mb-4 group-hover:scale-105 transition-transform`}>{currentOpponent.abbreviation}</div>
                    <div className="font-black text-white text-xl">{currentOpponent.nickname}</div>
                    <div className="text-xs text-slate-500">{currentOpponent.stats.wins}-{currentOpponent.stats.losses}</div>
                  </div>
                </div>
                <button onClick={handleSimulateUserGame} disabled={loading} className="w-full py-5 bg-white text-slate-900 font-black text-lg rounded-2xl hover:bg-emerald-400 transition-colors disabled:opacity-50">
                  {loading ? 'SIMULATING BROADCAST...' : 'KICKOFF GAME'}
                </button>
              </div>
            )}
          </div>
        </section>

        {/* Storylines Section */}
        <section className="space-y-4">
          <h3 className="text-xl font-black text-white flex items-center gap-2">
            <ICONS.Lightning className="text-emerald-500" /> Around the League
          </h3>
          <div className="grid grid-cols-1 gap-4">
            {storylines.length === 0 ? (
              <div className="p-8 bg-slate-800/50 border border-dashed border-slate-700 rounded-3xl text-center text-slate-500 italic">No news yet this week. Check back after simulations.</div>
            ) : (
              storylines.map(s => (
                <div key={s.id} className="bg-slate-800 p-6 rounded-3xl border border-slate-700 hover:border-slate-500 transition-colors group cursor-default">
                  <div className="flex justify-between items-start mb-2">
                    <h4 className="text-lg font-bold text-white group-hover:text-emerald-400 transition-colors">{s.title}</h4>
                    <span className={`text-[10px] font-black px-2 py-0.5 rounded ${s.importance === 'HIGH' ? 'bg-red-500/20 text-red-400' : 'bg-blue-500/20 text-blue-400'}`}>
                      {s.importance}
                    </span>
                  </div>
                  <p className="text-slate-400 text-sm leading-relaxed">{s.content}</p>
                  <div className="mt-3 flex gap-2">
                    {s.tags.map(t => <span key={t} className="text-[9px] text-slate-500 uppercase font-bold">#{t}</span>)}
                  </div>
                </div>
              ))
            )}
          </div>
        </section>
      </div>

      {/* Sidebar: Standings & Recruiting */}
      <div className="space-y-8">
        <section className="bg-slate-800 rounded-3xl border border-slate-700 p-6">
          <h3 className="text-sm font-black text-slate-500 uppercase mb-4 tracking-widest">{userTeam?.conference} Standings</h3>
          <div className="space-y-3">
            {getStandings(league.filter(t => t.conference === userTeam?.conference)).slice(0, 5).map((t, i) => (
              <div key={t.id} className={`flex justify-between items-center p-2 rounded-xl ${t.id === userTeamId ? 'bg-emerald-500/10' : ''}`}>
                <div className="flex items-center gap-3">
                  <span className="text-xs font-bold text-slate-600 w-4">{i+1}</span>
                  <div className={`w-2 h-2 rounded-full ${t.color}`}></div>
                  <span className={`text-sm font-bold ${t.id === userTeamId ? 'text-white' : 'text-slate-300'}`}>{t.name}</span>
                </div>
                <span className="text-xs font-mono text-slate-500">{t.stats.wins}-{t.stats.losses}</span>
              </div>
            ))}
          </div>
          <button onClick={() => setActiveTab(TABS.STANDINGS)} className="w-full mt-4 py-2 text-xs font-bold text-emerald-500 hover:text-emerald-400">View Full Standings &rarr;</button>
        </section>

        <section className="bg-slate-800 rounded-3xl border border-slate-700 p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest">Recruiting Board</h3>
            <span className="text-xs font-bold text-emerald-500">{recruitingPoints} pts</span>
          </div>
          <div className="space-y-4">
            {recruits.filter(r => r.isTargeted).slice(0, 3).map(r => (
              <div key={r.id} className="flex justify-between items-center bg-slate-900/50 p-3 rounded-2xl border border-slate-700/50">
                <div>
                  <div className="text-xs font-bold text-white">{r.name}</div>
                  <div className="text-[10px] text-slate-500">{r.position} • {r.stars}★</div>
                </div>
                <div className="w-10 h-10 rounded-full border-2 border-slate-700 flex items-center justify-center text-[10px] font-bold text-emerald-400">
                  {r.interest}%
                </div>
              </div>
            ))}
            {recruits.filter(r => r.isTargeted).length === 0 && <p className="text-xs text-slate-500 italic text-center py-4">No targets set.</p>}
          </div>
          <button onClick={() => setActiveTab(TABS.RECRUITING)} className="w-full mt-4 py-3 bg-slate-700 hover:bg-slate-600 rounded-xl text-xs font-bold text-white transition-colors">Manage Recruiting</button>
        </section>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 selection:bg-emerald-500/30">
      <header className="bg-slate-900/50 border-b border-slate-800 sticky top-0 z-50 backdrop-blur-xl">
        <div className="max-w-7xl mx-auto px-6 flex justify-between items-center h-20">
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-900/20">
              <ICONS.Football className="text-white w-6 h-6" />
            </div>
            <div className="leading-tight">
              <span className="block font-black text-xl tracking-tighter text-white">DYNASTY <span className="text-emerald-500 italic">25</span></span>
              <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">College Football Manager</span>
            </div>
          </div>
          {viewState === 'DYNASTY_HUB' && (
            <nav className="hidden lg:flex gap-2">
              {Object.values(TABS).map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveTab(tab)}
                  className={`px-4 py-2 text-xs font-black rounded-xl transition-all uppercase tracking-widest ${activeTab === tab ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/20' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                >
                  {tab}
                </button>
              ))}
            </nav>
          )}
          {userTeam && (
            <div className="flex items-center gap-4">
               <div className="text-right hidden sm:block">
                  <div className="text-[10px] font-black text-slate-500 uppercase">{userTeam.nickname}</div>
                  <div className="text-sm font-black text-white">{userTeam.stats.wins}-{userTeam.stats.losses}</div>
               </div>
               <div className={`w-10 h-10 rounded-xl ${userTeam.color} shadow-lg border border-white/10`}></div>
            </div>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-10">
        {viewState === 'CREATE_COACH' && (
          <div className="max-w-2xl mx-auto bg-slate-800 rounded-3xl border border-slate-700 p-10 shadow-3xl">
            <h1 className="text-4xl font-black text-white mb-2">The Journey Begins</h1>
            <p className="text-slate-400 mb-8">Create your coaching profile to start your legacy.</p>
            <div className="space-y-6">
              <input type="text" placeholder="COACH NAME" value={coach.name} onChange={e => setCoach({...coach, name: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-2xl p-5 text-white font-black text-lg focus:border-emerald-500 outline-none" />
              <input type="text" placeholder="ALMA MATER" value={coach.almaMater} onChange={e => setCoach({...coach, almaMater: e.target.value})} className="w-full bg-slate-900 border border-slate-700 rounded-2xl p-5 text-white font-bold focus:border-emerald-500 outline-none" />
              <button onClick={handleCreateCoach} className="w-full py-5 bg-emerald-600 hover:bg-emerald-500 text-white font-black text-xl rounded-2xl transition-all shadow-2xl shadow-emerald-900/40">SIGN CONTRACT</button>
            </div>
          </div>
        )}

        {viewState === 'JOB_OFFERS' && (
          <div className="space-y-8 animate-fade-in">
            <div className="text-center">
              <h1 className="text-5xl font-black text-white tracking-tighter mb-4">Job Board</h1>
              <p className="text-slate-400">These programs are looking for a new leader. Choose wisely.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {jobOffers.map(t => (
                <div key={t.id} className="bg-slate-800 rounded-3xl border border-slate-700 p-8 hover:border-emerald-500 transition-all group relative overflow-hidden">
                  <div className={`absolute top-0 right-0 p-8 opacity-5 group-hover:opacity-10 transition-opacity`}>
                    <ICONS.Football className="w-32 h-32" />
                  </div>
                  <h2 className="text-3xl font-black text-white mb-1 group-hover:text-emerald-400 transition-colors">{t.name}</h2>
                  <div className="text-sm font-bold text-slate-500 mb-6 uppercase tracking-widest">{t.conference}</div>
                  <div className="space-y-2 mb-8">
                    <div className="flex justify-between text-sm">
                      <span className="text-slate-500">Prestige</span>
                      <span className="text-white font-black">{t.prestige}</span>
                    </div>
                    <div className="w-full h-1 bg-slate-900 rounded-full">
                       <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${t.prestige}%` }}></div>
                    </div>
                  </div>
                  <button onClick={() => handleSelectJob(t.id)} className="w-full py-4 bg-slate-700 hover:bg-emerald-600 text-white font-black rounded-2xl transition-all shadow-lg">ACCEPT OFFER</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {viewState === 'DYNASTY_HUB' && (
          <>
            {activeTab === TABS.DASHBOARD && renderDashboard()}
            {activeTab === TABS.STRATEGY && userTeam && <StrategyPanel strategy={userTeam.strategy} onUpdate={s => setLeague(l => l.map(t => t.id === userTeamId ? {...t, strategy: s} : t))} />}
            {/* Other tabs would go here, following the same refined aesthetic */}
            {activeTab === TABS.ROSTER && (
              <div className="bg-slate-800 rounded-3xl border border-slate-700 overflow-hidden">
                <div className="p-8 border-b border-slate-700 flex justify-between items-center">
                  <h2 className="text-2xl font-black text-white">Depth Chart</h2>
                  <span className="text-sm font-bold text-slate-500 uppercase tracking-widest">{userTeam?.roster.length} Active Players</span>
                </div>
                <div className="divide-y divide-slate-700/50">
                  {userTeam?.roster.sort((a,b) => b.rating - a.rating).map(p => (
                    <div key={p.id} className="p-6 flex justify-between items-center hover:bg-slate-700/20 transition-colors">
                      <div className="flex items-center gap-6">
                        <div className="text-xl font-black text-slate-700 w-8">{p.position}</div>
                        <div>
                          <div className="font-black text-white text-lg">{p.name}</div>
                          <div className="text-xs text-slate-500 font-bold uppercase tracking-widest">{p.year} • {p.hometown}</div>
                        </div>
                      </div>
                      <div className="flex items-center gap-8">
                        <div className="text-center">
                          <div className="text-2xl font-black text-emerald-400">{p.rating}</div>
                          <div className="text-[10px] font-black text-slate-600 uppercase">OVR</div>
                        </div>
                        <ICONS.ChevronDown className="text-slate-700" />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </>
        )}
      </main>
    </div>
  );
};

export default App;

