export const calculateStars = (prestige: number): number => {
  if (prestige >= 90) return 6;
  if (prestige >= 80) return 5;
  if (prestige >= 65) return 4;
  if (prestige >= 50) return 3;
  if (prestige >= 35) return 2;
  return 1;
};

